import {mount,esc,money,pct,options,revisionForm,versionSelect,delta,methodDetails,limits} from '../shared/experience.js';
const labels={baseline:'Portefeuille initial',minimum_turnover:'Minimum calculé',alternative_minimum:'Autre minimum',simple_reference:'Règle simple'};
const name=o=>labels[o.id]||o.label;
const button=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const proof=(text,type='minimum_reallocation')=>button(text,'proof',`data-proof="${type}"`,'text-button');
function chart(s,list){
 const budget=s.v.problem.scenario_loss_limit_cad, cap=Math.max(budget||0,...list.flatMap(o=>Object.values(o.losses||{})),1);
 const step=cap>10000?5000:cap>1000?1000:Math.max(1,Math.pow(10,Math.floor(Math.log10(cap))));
 const max=Math.ceil(cap/step)*step, x=v=>180+v/max*490, rowHeight=76, end=56+list.length*rowHeight;
 const ticks=Array.from({length:6},(_,i)=>i*max/5);
 return `<div class="plot-wrap" tabindex="0" role="region" aria-label="Graphique des pertes, défilement horizontal sur petit écran"><svg viewBox="0 0 740 ${end+42}" role="img" aria-label="Pertes comparées dans les deux chocs hypothétiques, en dollars canadiens. Valeurs exactes dans le tableau sous le graphique."><defs><pattern id="minor-grid" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".55" fill="currentColor" opacity=".18"/></pattern></defs><rect x="180" y="30" width="490" height="${end-30}" fill="url(#minor-grid)"/>${ticks.map(t=>`<path class="axis" d="M${x(t)} 30V${end}"/><text class="tick" x="${x(t)}" y="${end+24}" text-anchor="middle">${money(t)}</text>`).join('')}${Number.isFinite(budget)?`<path class="budget-line" d="M${x(budget)} 28V${end}"/><text class="budget-label" x="${Math.min(x(budget),650)}" y="17" text-anchor="end">LIMITE ${money(budget)} CAD</text>`:''}${list.map((o,i)=>{
 const y=59+i*rowHeight,a=o.losses?.actions,b=o.losses?.obligations;
 return `<g class="plot-option ${s.selected===o.id?'selected':''}"><text x="0" y="${y}" class="plot-name">${esc(name(o))}</text><text x="0" y="${y+19}" class="plot-state">${o.admissible?'CONTRAINTES RESPECTÉES':'HORS CONTRAINTES'}</text>${Number.isFinite(a)?`<path class="measure solid" d="M180 ${y-2}H${x(a)}"/><circle cx="${x(a)}" cy="${y-2}" r="4.5"/><text x="${x(a)+10}" y="${y+2}" class="value">${money(a)}</text>`:''}${Number.isFinite(b)?`<path class="measure hollow" d="M180 ${y+22}H${x(b)}"/><rect class="square" x="${x(b)-4}" y="${y+18}" width="8" height="8"/><text x="${x(b)+10}" y="${y+26}" class="value">${money(b)}</text>`:''}</g>`;
 }).join('')}</svg></div>`;
}
function comparisons(s){
 const all=options(s), valid=all.filter(o=>o.id!=='baseline');
 const list=s.view==='compare'||s.level==='deep'?all:[...valid.filter(o=>['minimum_turnover','simple_reference'].includes(o.id)),...all.filter(o=>o.id==='baseline')];
 if(!all.length)return `<section class="measurement"><div class="section-line"><span>02 / FAISABILITÉ</span><span>AUCUNE ALLOCATION</span></div><h2>Les contraintes ne se rejoignent pas.</h2><p>${esc(s.v.analysis?.status==='infeasible'?'Le calcul conclut à une impossibilité sous les paramètres actuels. Modifier une hypothèse permet de l’examiner à nouveau.':'Aucun résultat admissible disponible avec ces entrées.')}</p>${button('Ajuster les paramètres ↗','view','data-view="revise"')}</section>`;
 const multiple=all.some(o=>o.id==='alternative_minimum')||!!s.v.simple_reference;
 return `<section class="measurement"><div class="section-line"><span>02 / CHAMP DE COMPARAISON</span><span>CAD · À ${esc(s.v.problem.withdrawal_months)} MOIS</span></div><div class="measure-heading"><h2>${multiple?'Même question.<br>Pertes différentes.':'Ce que montrent<br>les deux chocs.'}</h2><p>● Choc actions<br>□ Choc obligations<br><span>Deux hypothèses, aucune probabilité.</span></p></div>${chart(s,list)}<div class="table-scroll" tabindex="0" role="region" aria-label="Tableau comparatif"><table><caption>Résultats exacts · sélectionner une option pour examiner sa composition</caption><thead><tr><th>OPTION</th><th>RÉALLOUÉ</th><th>PERTE ACTIONS</th><th>PERTE OBLIG.</th></tr></thead><tbody>${list.map(o=>`<tr class="${s.selected===o.id?'active-row':''}"><th>${button(esc(name(o))+(s.selected===o.id?' ←':''),'select',`data-option="${esc(o.id)}"`)}${o.reference?'<small>Contrôle indépendant · r5</small>':''}</th><td>${money(o.turnover)}</td><td>${money(o.losses?.actions)}</td><td>${money(o.losses?.obligations)}</td></tr>`).join('')}</tbody></table></div>${allocationDetail(s,all)}${s.view!=='compare'?button('Comparer toutes les options →','view','data-view="compare"','full-button'):''}</section>`;
}
function allocationDetail(s,all){
 const o=all.find(o=>o.id===s.selected)||all.find(o=>o.id==='minimum_turnover');if(!o)return '';
 return `<div class="composition"><div class="section-line"><span>COMPOSITION / ${esc(name(o))}</span><span>POIDS INITIAUX</span></div><div class="allocation-strip">${Object.entries(o.weights||{}).filter(([,v])=>v>0).map(([t,v],i)=>`<div class="asset a${i}" style="flex:${v}" title="${esc(t)} : ${pct(v)}"><span>${esc(t==='RESERVE_ABSTRAITE'?'RÉSERVE':t.replace('.TO',''))}</span><strong>${pct(v)}</strong></div>`).join('')}</div><p class="fine">La réserve est une hypothèse à rendement nul, pas un instrument garanti.</p></div>`;
}
function controls(s){const p=s.v.problem;
 return `<aside class="controls" aria-label="Conditions du dossier"><div class="rail-title">01 / CONDITIONS D’ENTRÉE</div><div class="profile"><span class="person-mark" aria-hidden="true">R/</span><div><strong>Robert</strong><span>Dossier fictif · ${s.local?'variante locale':esc(s.v.id)}</span></div></div><dl class="settings"><div><dt>Capital déclaré</dt><dd>${money(p.capital_cad)} <small>CAD</small></dd></div><div><dt>Retrait à financer</dt><dd>${money(p.withdrawal_cad)} <small>CAD</small></dd><dd class="annotation">à ${esc(p.withdrawal_months)} mois</dd></div><div><dt>Budget de perte / choc</dt><dd>${money(p.scenario_loss_limit_cad)} <small>CAD</small></dd></div><div><dt>Plafond TSLA initial</dt><dd>${pct(p.max_asset_weights?.TSLA)}</dd></div></dl>${button('MODIFIER UNE HYPOTHÈSE ↗','view','data-view="revise"','control-action')}<div class="left-note"><span>HORIZON DÉCLARÉ</span><strong>${esc(p.horizon_years||4)} ans</strong><p>Les calculs présentés portent sur le retrait à ${esc(p.withdrawal_months)} mois. Le solde n’est pas projeté à quatre ans.</p></div><div class="archive-select"><label>ARCHIVES DU DOSSIER</label>${versionSelect(s)}<p>Versions déjà calculées. Aucun agent ne s’exécute à leur ouverture.</p></div><div class="rail-bottom"><span aria-hidden="true">+ ────────────── +</span><p>La présentation change.<br>Les résultats restent identiques.</p></div></aside>`;
}
function journal(s){return `<aside class="journal" aria-label="Registre des preuves"><div class="rail-title">04 / REGISTRE DE PREUVE</div><p class="journal-intro">Remonter du chiffre<br>à sa condition de validité.</p><ol class="proof-list"><li><span>01</span><div>${proof('Le minimum ↗')}<p>Formulation, résultat, contraintes contrôlées.</p></div></li><li><span>02</span><div>${proof('La méthode ↗','method')}<p>Programme linéaire. Optimum conditionnel au modèle.</p></div></li><li><span>03</span><div>${proof('Les sources ↗','sources')}<p>Passages consultés, portée et limites documentaires.</p></div></li></ol><div class="agent-register"><div class="section-line"><span>EXÉCUTION ARCHIVÉE</span></div>${(s.v.agents||[]).map((a,i)=>`<button data-action="proof" data-proof="agents"><span>${String(i).padStart(2,'0')}</span><strong>${esc(a.name)}</strong><span class="run-status">${a.status==='complete'?'[✓]':'[·]'}</span></button>`).join('')}<p>${s.local?'Cette variante utilise le calcul local. Les agents affichés appartiennent à l’archive de départ.':'Contributions enregistrées dans le dossier. Les coches ne constituent pas une vérification indépendante.'}</p></div><div class="stamp"><span>PORTÉE DU RÉSULTAT</span><strong>CONDITIONNEL</strong><p>Chocs hypothétiques.<br>Pas de garantie de perte maximale.</p></div></aside>`;}
function result(s){const n=s.v.stats?.min_reallocation_cad;
 return `<section class="readout"><div class="section-line"><span>RÉSULTAT / ${s.local?'CALCUL LOCAL':'ARCHIVE VÉRIFIABLE'}</span>${proof('OUVRIR LA PREUVE ↗')}</div><div class="result-number">${Number.isFinite(n)?money(n):'—'}<span>CAD</span></div><h1>${Number.isFinite(n)?'À réallouer au minimum.':'Aucune allocation proposée.'}</h1><p>${Number.isFinite(n)?`Pour financer ${money(s.v.problem.withdrawal_cad)} CAD de retrait en respectant les contraintes de ce modèle.`:'Examiner le conflit avant de modifier les paramètres.'}</p>${s.v.simple_reference?`<div class="critical"><b>≠</b><p><strong>Une règle simple atteint aussi ce minimum.</strong><br>Ce résultat ne démontre pas la supériorité des agents, ni le risque le plus faible.</p></div>`:Number.isFinite(n)?`<div class="critical"><b>∴</b><p>Le minimum réduit le capital déplacé. Il ne minimise ni la perte, ni les frais réels.</p></div>`:`<div class="critical"><b>!</b><p>Aucun minimum ni allocation admissible établis. Les contraintes doivent être réexaminées avant toute conclusion.</p></div>`}</section>`;
}
function revision(s){return `<section class="revision"><div class="section-line"><span>03 / EXPÉRIENCE CONTRÔLÉE</span><span>COPIE LOCALE</span></div><h1>Changer une entrée.<br>Observer la différence.</h1><p>Les autres paramètres restent ceux du dossier sélectionné. Le calcul s’exécute sur une copie, sans modifier l’archive ni relancer les agents.</p>${revisionForm(s)}<div class="try-line">${button('Préparer un retrait de 40 000 CAD','draft','data-withdrawal="40000"','text-button')}<span>Remplit le champ. Ne lance pas le calcul.</span></div></section>`;}
function render(s){const deep=s.level==='deep';
 return `<header class="top"><a class="brand" href="../index.html" aria-label="Retour aux directions">ALPHAFORGE<span>LABORATOIRE DE DÉCISION</span></a><div class="direction"><span>02</span><strong>ISObare</strong></div><div class="mode-toggle" aria-label="Niveau d’explication">${button('Lecture directe','level',`data-level="accessible" aria-pressed="${!deep}"`,!deep?'on':'')}${button('Lecture instrumentée','level',`data-level="deep" aria-pressed="${deep}"`,deep?'on':'')}</div></header><div class="subtop" role="region" aria-label="Repères du dossier"><span>ROBERT / RETRAIT PROGRAMMÉ</span><span>ÉTUDE CONDITIONNELLE · MONNAIE CAD</span><span class="status-dot">${s.busy?'CALCUL EN COURS':s.local?'VARIANTE LOCALE':'ARCHIVE CHARGÉE'}</span></div><div class="console ${deep?'deep':''}">${controls(s)}<main id="main"><nav class="view-nav" aria-label="Parcours du dossier">${['overview','compare','revise'].map((v,i)=>button(`${String(i+1).padStart(2,'0')} ${['Lire le résultat','Comparer','Faire varier'][i]}`,'view',`data-view="${v}" aria-pressed="${s.view===v}"`,s.view===v?'on':'')).join('')}${s.previous?button('↶ Revenir','undo','','undo'):''}</nav>${s.error?`<div class="error" role="alert">${esc(s.error)}<br>Les paramètres restent modifiables ; aucun dossier n’est écrasé.</div>`:''}${s.notice?`<div class="notice" role="status">${esc(s.notice)}</div>`:''}${s.local?'<div class="local-label">COPIE EXPLORATOIRE · CALCUL DÉTERMINISTE · AUCUN AGENT RELANCÉ</div>':''}${s.view==='revise'?revision(s):`${deep?'<div class="technical-intro">PROBLÈME / MINIMISER ½ × Σ |w − w₀| · SOUS CONTRAINTES</div>':''}${result(s)}${s.previous?`<section class="delta-region"><div class="section-line"><span>Δ / CE QUI CHANGE</span><span>COMPARAISON DES ÉTATS</span></div>${delta(s)}${button('Annuler cette variante ↶','undo')}</section>`:''}${deep?`<section class="method-region"><div class="section-line"><span>FORMULATION / AVANT INTERPRÉTATION</span></div>${methodDetails(s)}</section>`:""}${comparisons(s)}`}<section class="scope-region"><div class="section-line"><span>DOMAINE DE VALIDITÉ</span></div>${limits(s)}</section></main>${journal(s)}</div><footer><span>ISObare / Instrument de comparaison</span><span>PROTOTYPE · DIRECTION ARTISTIQUE À VALIDER</span><a href="../index.html">Retour aux trois directions ↗</a></footer>`;
}
mount(render,{name:'Isobare'});
